mapper.select:
SELECT a.`id` `id`, a.`record_id` `recordId`, a.`data_time` `dataTime`, a.`direction` `direction`, a.`lane` `lane`, a.`traffic_volume` `trafficVolume`, a.`average_speed` `averageSpeed`, a.`time_occupancy_rate` `timeOccupancyRate`, a.`average_headway` `averageHeadway`, a.`average_time_interval` `averageTimeInterval`, b.`code` `deviceCode`, b.`area_name` `areaName`
FROM `vehicle_flow_monitoring` a LEFT JOIN `security_device` b ON a.`device_id` = b.`third_party_id`
and a.`data_time` >= #{st}
and a.`data_time` <= #{et}
order by a.`data_time` DESC

SELECT
    SUM( `traffic_volume` )
FROM
    `vehicle_flow_monitoring`


        and `data_time` >= #{st}


        and `data_time` <= #{et}


        and `direction` = #{direction}

SELECT
COALESCE(sum(`traffic_volume`), 0 ) `num`,
DATE_FORMAT(`data_time`,${dateFormat}) `timeFlag`
FROM
`vehicle_flow_monitoring`


        and `data_time` >= #{st}


        and `data_time` <= #{et}


        and `direction` = #{direction}


GROUP BY
DATE_FORMAT(`data_time`, ${dateFormat})

SELECT
COALESCE(sum(`traffic_volume`), 0 ) `num`,
DATE_FORMAT(`data_time`,${dateFormat}) `timeFlag`
FROM
`vehicle_flow_monitoring`


        and `data_time` >= #{st}


        and `data_time` <= #{et}


        and `direction` = #{direction}


GROUP BY
DATE_FORMAT(`data_time`, ${dateFormat})

SELECT
COALESCE(sum(`traffic_volume`), 0 ) `num`,
to_char(`data_time`,${dateFormat}) `timeFlag`
FROM
`vehicle_flow_monitoring`


        and `data_time` >= #{st}


        and `data_time` <= #{et}


        and `direction` = #{direction}


GROUP BY
to_char(`data_time`, ${dateFormat})

SELECT COALESCE ( SUM( IF ( `direction` = 'DIRECTION_IN', `traffic_volume`, 0 )), 0 ) AS `inNum`, COALESCE ( SUM( IF ( `direction` = 'DIRECTION_OUT', `traffic_volume`, 0 )), 0 ) AS `outNum`, lane FROM `vehicle_flow_monitoring`
and `data_time` >= #{st}
and `data_time` <= #{et}
GROUP BY `lane`

SELECT
COALESCE(avg(`average_speed`), 0 ) `speed`,
DATE_FORMAT(`data_time`,${dateFormat}) `timeFlag`
FROM
`vehicle_flow_monitoring`


        and `data_time` >= #{st}


        and `data_time` <= #{et}


        and `direction` = #{direction}


GROUP BY
DATE_FORMAT(`data_time`, ${dateFormat})

SELECT
COALESCE(avg(`average_speed`), 0 ) `speed`,
DATE_FORMAT(`data_time`,${dateFormat}) `timeFlag`
FROM
`vehicle_flow_monitoring`


        and `data_time` >= #{st}


        and `data_time` <= #{et}


        and `direction` = #{direction}


GROUP BY
