SELECT
COALESCE(avg(`average_speed`), 0 ) `speed`,
to_char(`data_time`,${dateFormat}) `timeFlag`
FROM
`vehicle_flow_monitoring`


        and `data_time` >= #{st}


        and `data_time` <= #{et}


        and `direction` = #{direction}


GROUP BY
to_char(`data_time`, ${dateFormat})
